import itertools, random
from reduce import reduce

def clique_yes(n, edges, k):
    if k <= 0: return True
    if k > n: return False
    adj = {frozenset(e) for e in edges}
    for size in range(k, n+1):
        for s in itertools.combinations(range(n), size):
            if all(frozenset(p) in adj for p in itertools.combinations(s, 2)):
                return True
    return False

def vc_yes(n, edges, k):
    if k < 0: return False
    if not edges: return True
    if k >= n: return True
    for size in range(0, k+1):
        for s in itertools.combinations(range(n), size):
            cov = set(s)
            if all(u in cov or v in cov for u, v in edges):
                return True
    return False

rng = random.Random(7)
bad = 0
for _ in range(20000):
    n = rng.randint(0, 7)
    pairs = list(itertools.combinations(range(n), 2))
    edges = [list(p) for p in pairs if rng.random() < 0.5]
    k = rng.randint(-3, n + 3)
    inst = {"n": n, "edges": edges, "k": k}
    r = reduce(inst)
    a = clique_yes(n, edges, k)
    b = vc_yes(r["n"], r["edges"], r["k"])
    if a != b:
        bad += 1
        if bad <= 5: print("MISMATCH", inst, r, a, b)
print("mismatches:", bad)
EOF"}

